using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using System.Text.RegularExpressions;
using WhatsBiz.Application.Common.Interfaces;
using WhatsBiz.Application.Common.Exceptions;
using WhatsBiz.Application.Features.Storefront;

namespace WhatsBiz.Infrastructure.Storefront;

public sealed class StorefrontFeedbackService(IConfiguration configuration, IStorefrontCustomerService customers, IStorefrontMediaStorage media, IStorefrontFeedbackAttachmentScanner scanner, ILogger<StorefrontFeedbackService> logger) : IStorefrontFeedbackService
{
    private string ConnectionString => configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Database connection unavailable.");
    public Task<Guid?> ResolveTenantAsync(string storeKey, CancellationToken token) => TenantAsync(storeKey, token);
    public async Task<StorefrontFeedbackTicketDto> SubmitAsync(string storeKey, string? sessionToken, StorefrontFeedbackInput input, CancellationToken token)
    {
        var tenant = await TenantAsync(storeKey, token) ?? throw new EntityNotFoundException("Store was not found.");
        var customer = string.IsNullOrWhiteSpace(sessionToken) ? null : await customers.GetSessionAsync(storeKey, sessionToken, token);
        var type = Normalize(input.FeedbackType, "SUGGESTION", "COMPLAINT"); var category = Normalize(input.Category, "ORDER", "PRODUCT", "DELIVERY", "PAYMENT_REFUND", "CUSTOMER_SERVICE", "OTHER");
        var subject = Required(input.Subject, 200, "Enter a subject."); var description = Required(input.Description, 4000, "Enter a description.");
        var guestName = customer is null ? Required(input.GuestName, 250, "Enter your name.") : null;
        var guestMobile = customer is null ? NormalizePhone(input.GuestMobile) : null;
        if (customer is null && guestMobile is null) throw new BusinessRuleException("Enter a valid mobile number.");
        await using var connection = new SqlConnection(ConnectionString); await connection.OpenAsync(token);
        if (input.OrderId is Guid orderId)
        {
            await using var order = new SqlCommand("SELECT COUNT(1) FROM sales.SalesInvoices i JOIN integration.WhatsAppCommerceOrders w ON w.TenantId=i.TenantId AND w.InvoiceId=i.InvoiceId AND w.SourceChannel=N'STOREFRONT' WHERE i.TenantId=@tenant AND i.InvoiceId=@order AND (@customer IS NULL OR i.CustomerId=@customer);", connection);
            Add(order, "@tenant", tenant); Add(order, "@order", orderId); Add(order, "@customer", customer?.Id);
            if ((int)(await order.ExecuteScalarAsync(token) ?? 0) != 1) throw new BusinessRuleException("The selected order is not available for this account.");
        }
        var ticketId = Guid.NewGuid(); var reference = $"FB-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
        await using var command = new SqlCommand("INSERT commerce.StorefrontFeedbackTickets(TicketId,TenantId,TicketReference,CustomerId,GuestName,GuestMobile,FeedbackType,Category,Subject,Description,OrderId) VALUES(@id,@tenant,@reference,@customer,@name,@mobile,@type,@category,@subject,@description,@order);", connection);
        Add(command, "@id", ticketId); Add(command, "@tenant", tenant); Add(command, "@reference", reference); Add(command, "@customer", customer?.Id); Add(command, "@name", guestName); Add(command, "@mobile", guestMobile); Add(command, "@type", type); Add(command, "@category", category); Add(command, "@subject", subject); Add(command, "@description", description); Add(command, "@order", input.OrderId);
        try { await command.ExecuteNonQueryAsync(token); } catch (SqlException ex) when (ex.Number is 2601 or 2627) { throw new BusinessRuleException("Please submit again in a moment."); }
        var result = new StorefrontFeedbackTicketDto(ticketId, reference, type, category, subject, description, input.OrderId, "MEDIUM", "OPEN", null, DateTimeOffset.UtcNow, DateTimeOffset.UtcNow, customer?.Name, customer?.Mobile ?? guestMobile);
        try { await CreateNotificationsAsync(tenant, result, "NEW_TICKET", token); await QueueExternalDeliveriesAsync(tenant, ticketId, token); } catch (Exception ex) { FeedbackLogs.NotificationEnqueueFailed(logger, ex, tenant, ticketId); }
        return result;
    }
    public async Task<IReadOnlyCollection<StorefrontFeedbackTicketDto>?> CustomerTicketsAsync(string storeKey, string sessionToken, CancellationToken token)
    { var customer = await customers.GetSessionAsync(storeKey, sessionToken, token); if (customer is null) return null; var tenant = await TenantAsync(storeKey, token); return tenant is null ? null : await TicketsAsync(tenant.Value, customer.Id, token); }
    public async Task<StorefrontFeedbackTicketDetailDto?> CustomerTicketAsync(string storeKey, string sessionToken, Guid ticketId, CancellationToken token)
    { var customer = await customers.GetSessionAsync(storeKey, sessionToken, token); var tenant = await TenantAsync(storeKey, token); return customer is null || tenant is null ? null : await DetailAsync(tenant.Value, ticketId, customer.Id, false, token); }
    public async Task<StorefrontFeedbackPageDto> SearchAsync(Guid tenantId, string? search, string? feedbackType, string? status, string? priority, int pageNumber, int pageSize, CancellationToken token)
    {
        pageNumber=Math.Clamp(pageNumber,1,1_000_000); pageSize=Math.Clamp(pageSize,1,100); search=Limit(search,100); feedbackType=Limit(feedbackType,20); status=Limit(status,20); priority=Limit(priority,10);
        await using var c=new SqlConnection(ConnectionString); await c.OpenAsync(token);
        const string predicate="t.TenantId=@tenant AND (@search IS NULL OR t.TicketReference LIKE N'%'+@search+N'%' OR t.Subject LIKE N'%'+@search+N'%' OR t.GuestMobile LIKE N'%'+@search+N'%' OR c.CustomerName LIKE N'%'+@search+N'%' OR c.Mobile LIKE N'%'+@search+N'%') AND (@type IS NULL OR t.FeedbackType=@type) AND (@status IS NULL OR t.Status=@status) AND (@priority IS NULL OR t.Priority=@priority)";
        var countSql=$"SELECT COUNT(1),SUM(CASE WHEN t.Status IN(N'OPEN',N'REOPENED') THEN 1 ELSE 0 END),SUM(CASE WHEN t.Status=N'IN_PROGRESS' THEN 1 ELSE 0 END),SUM(CASE WHEN t.Status=N'RESOLVED' THEN 1 ELSE 0 END),SUM(CASE WHEN t.Status=N'CLOSED' THEN 1 ELSE 0 END),SUM(CASE WHEN t.Priority IN(N'HIGH',N'URGENT') AND t.Status NOT IN(N'RESOLVED',N'CLOSED') THEN 1 ELSE 0 END),SUM(CASE WHEN t.CreatedAtUtc<=DATEADD(HOUR,-72,SYSUTCDATETIME()) AND t.Status NOT IN(N'RESOLVED',N'CLOSED') THEN 1 ELSE 0 END) FROM commerce.StorefrontFeedbackTickets t LEFT JOIN sales.Customers c ON c.TenantId=t.TenantId AND c.CustomerId=t.CustomerId WHERE {predicate};";
        await using var count=new SqlCommand(countSql,c); Add(count,"@tenant",tenantId); Add(count,"@search",search); Add(count,"@type",feedbackType); Add(count,"@status",status); Add(count,"@priority",priority); await using var cr=await count.ExecuteReaderAsync(token); await cr.ReadAsync(token); var total=cr.GetInt32(0); var open=cr.IsDBNull(1)?0:cr.GetInt32(1); var pending=cr.IsDBNull(2)?0:cr.GetInt32(2); var resolved=cr.IsDBNull(3)?0:cr.GetInt32(3); var closed=cr.IsDBNull(4)?0:cr.GetInt32(4); var high=cr.IsDBNull(5)?0:cr.GetInt32(5); var overdue=cr.IsDBNull(6)?0:cr.GetInt32(6); await cr.CloseAsync();
        var sql=$"SELECT t.TicketId,t.TicketReference,t.FeedbackType,t.Category,t.Subject,t.Description,t.OrderId,t.Priority,t.Status,t.CustomerVisibleReply,t.CreatedAtUtc,t.UpdatedAtUtc,COALESCE(c.CustomerName,t.GuestName),COALESCE(c.Mobile,t.GuestMobile) FROM commerce.StorefrontFeedbackTickets t LEFT JOIN sales.Customers c ON c.TenantId=t.TenantId AND c.CustomerId=t.CustomerId WHERE {predicate} ORDER BY t.UpdatedAtUtc DESC OFFSET @skip ROWS FETCH NEXT @take ROWS ONLY;";
        await using var q=new SqlCommand(sql,c); Add(q,"@tenant",tenantId); Add(q,"@search",search); Add(q,"@type",feedbackType); Add(q,"@status",status); Add(q,"@priority",priority); Add(q,"@skip",(pageNumber-1)*pageSize); Add(q,"@take",pageSize); var rows=new List<StorefrontFeedbackTicketDto>(); await using var r=await q.ExecuteReaderAsync(token); while(await r.ReadAsync(token)) rows.Add(ReadTicket(r)); return new(rows,total,pageNumber,pageSize,open,pending,resolved,closed,high,overdue);
    }
    public Task<StorefrontFeedbackTicketDetailDto?> GetAsync(Guid tenantId, Guid ticketId, bool includeInternal, CancellationToken token) => DetailAsync(tenantId,ticketId,null,includeInternal,token);
    public async Task<StorefrontFeedbackTicketDetailDto> UpdateAsync(Guid tenantId, Guid actorUserId, Guid ticketId, UpdateStorefrontFeedbackInput input, CancellationToken token)
    {
        var current=await GetAsync(tenantId,ticketId,true,token)??throw new EntityNotFoundException("Feedback ticket was not found."); var status=input.Status is null?current.Ticket.Status:Normalize(input.Status,"OPEN","IN_PROGRESS","RESOLVED","CLOSED","REOPENED"); var priority=input.Priority is null?current.Ticket.Priority:Normalize(input.Priority,"LOW","MEDIUM","HIGH","URGENT");
        if(input.CustomerReply is null&&input.InternalNote is null&&status==current.Ticket.Status&&priority==current.Ticket.Priority&&!input.AssignedTo.HasValue) return current;
        await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);await using var tx=await c.BeginTransactionAsync(token);
        await using(var q=new SqlCommand("UPDATE commerce.StorefrontFeedbackTickets SET Status=@status,Priority=@priority,AssignedTo=COALESCE(@assigned,AssignedTo),CustomerVisibleReply=COALESCE(@reply,CustomerVisibleReply),UpdatedAtUtc=SYSUTCDATETIME(),ResolvedAtUtc=CASE WHEN @status IN(N'RESOLVED',N'CLOSED') THEN COALESCE(ResolvedAtUtc,SYSUTCDATETIME()) ELSE NULL END WHERE TenantId=@tenant AND TicketId=@id;",c,(SqlTransaction)tx)){Add(q,"@status",status);Add(q,"@priority",priority);Add(q,"@assigned",input.AssignedTo);Add(q,"@reply",string.IsNullOrWhiteSpace(input.CustomerReply)?null:Limit(input.CustomerReply,4000));Add(q,"@tenant",tenantId);Add(q,"@id",ticketId);await q.ExecuteNonQueryAsync(token);}
        await using(var a=new SqlCommand("INSERT commerce.StorefrontFeedbackTicketActivity(TenantId,TicketId,ActivityType,FromStatus,ToStatus,CustomerReply,InternalNote,ActorUserId) VALUES(@tenant,@id,N'UPDATE',@from,@to,@reply,@note,@actor);",c,(SqlTransaction)tx)){Add(a,"@tenant",tenantId);Add(a,"@id",ticketId);Add(a,"@from",current.Ticket.Status);Add(a,"@to",status);Add(a,"@reply",input.CustomerReply);Add(a,"@note",input.InternalNote);Add(a,"@actor",actorUserId);await a.ExecuteNonQueryAsync(token);} await tx.CommitAsync(token); var updated=await GetAsync(tenantId,ticketId,true,token) ?? throw new EntityNotFoundException("Feedback ticket was not found."); try { await CreateNotificationsAsync(tenantId, updated.Ticket, input.CustomerReply is not null ? "CUSTOMER_REPLY" : status != current.Ticket.Status ? "STATUS_CHANGED" : "TICKET_UPDATED", token); await QueueExternalDeliveriesAsync(tenantId, ticketId, token); } catch (Exception ex) { FeedbackLogs.NotificationEnqueueFailed(logger, ex, tenantId, ticketId); } return updated;
    }
    private async Task<IReadOnlyCollection<StorefrontFeedbackTicketDto>> TicketsAsync(Guid tenant,Guid customer,CancellationToken token){await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);await using var q=new SqlCommand("SELECT t.TicketId,t.TicketReference,t.FeedbackType,t.Category,t.Subject,t.Description,t.OrderId,t.Priority,t.Status,t.CustomerVisibleReply,t.CreatedAtUtc,t.UpdatedAtUtc,COALESCE(c.CustomerName,t.GuestName),COALESCE(c.Mobile,t.GuestMobile) FROM commerce.StorefrontFeedbackTickets t LEFT JOIN sales.Customers c ON c.TenantId=t.TenantId AND c.CustomerId=t.CustomerId WHERE t.TenantId=@tenant AND t.CustomerId=@customer ORDER BY t.UpdatedAtUtc DESC;",c);Add(q,"@tenant",tenant);Add(q,"@customer",customer);var rows=new List<StorefrontFeedbackTicketDto>();await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))rows.Add(ReadTicket(r));return rows;}
    private async Task<StorefrontFeedbackTicketDetailDto?> DetailAsync(Guid tenant,Guid id,Guid? customer,bool includeInternal,CancellationToken token){await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);var sql="SELECT t.TicketId,t.TicketReference,t.FeedbackType,t.Category,t.Subject,t.Description,t.OrderId,t.Priority,t.Status,t.CustomerVisibleReply,t.CreatedAtUtc,t.UpdatedAtUtc,COALESCE(c.CustomerName,t.GuestName),COALESCE(c.Mobile,t.GuestMobile) FROM commerce.StorefrontFeedbackTickets t LEFT JOIN sales.Customers c ON c.TenantId=t.TenantId AND c.CustomerId=t.CustomerId WHERE t.TenantId=@tenant AND t.TicketId=@id"+(customer.HasValue?" AND t.CustomerId=@customer":"")+";";await using var q=new SqlCommand(sql,c);Add(q,"@tenant",tenant);Add(q,"@id",id);Add(q,"@customer",customer);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))return null;var ticket=ReadTicket(r);await r.CloseAsync();var activities=new List<StorefrontFeedbackActivityDto>();var activitySql="SELECT ActivityType,FromStatus,ToStatus,CustomerReply,CreatedAtUtc"+(includeInternal?",InternalNote":" ,CAST(NULL AS NVARCHAR(4000))")+" FROM commerce.StorefrontFeedbackTicketActivity WHERE TenantId=@tenant AND TicketId=@id ORDER BY CreatedAtUtc";await using var a=new SqlCommand(activitySql,c);Add(a,"@tenant",tenant);Add(a,"@id",id);await using var ar=await a.ExecuteReaderAsync(token);while(await ar.ReadAsync(token))activities.Add(new(ar.GetString(0),ar.IsDBNull(1)?null:ar.GetString(1),ar.IsDBNull(2)?null:ar.GetString(2),ar.IsDBNull(3)?null:ar.GetString(3),ar.GetDateTimeOffset(4),ar.IsDBNull(5)?null:ar.GetString(5)));return new(ticket,activities);}
    public async Task<IReadOnlyCollection<StorefrontFeedbackNotificationDto>> NotificationsAsync(Guid tenantId, Guid? customerId, CancellationToken token)
    { await using var c=new SqlConnection(ConnectionString); await c.OpenAsync(token); const string sql="SELECT TOP(100)n.NotificationId,n.TicketId,t.TicketReference,n.Title,n.Message,n.IsRead,n.CreatedAtUtc,n.RecipientType FROM commerce.StorefrontFeedbackNotifications n JOIN commerce.StorefrontFeedbackTickets t ON t.TicketId=n.TicketId WHERE n.TenantId=@tenant AND ((n.RecipientType=N'ERP' AND @customer IS NULL) OR (n.RecipientType=N'CUSTOMER' AND n.CustomerId=@customer)) ORDER BY n.CreatedAtUtc DESC;"; await using var q=new SqlCommand(sql,c); Add(q,"@tenant",tenantId); Add(q,"@customer",customerId); var rows=new List<StorefrontFeedbackNotificationDto>(); await using var r=await q.ExecuteReaderAsync(token); while(await r.ReadAsync(token)) rows.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetBoolean(5),r.GetDateTimeOffset(6),r.GetString(7))); return rows; }
    public async Task<bool> MarkNotificationReadAsync(Guid tenantId, Guid notificationId, Guid? customerId, CancellationToken token)
    { await using var c=new SqlConnection(ConnectionString); await c.OpenAsync(token); const string sql="UPDATE commerce.StorefrontFeedbackNotifications SET IsRead=1,ReadAtUtc=COALESCE(ReadAtUtc,SYSUTCDATETIME()) WHERE TenantId=@tenant AND NotificationId=@id AND ((RecipientType=N'ERP' AND @customer IS NULL) OR (RecipientType=N'CUSTOMER' AND CustomerId=@customer));"; await using var q=new SqlCommand(sql,c); Add(q,"@tenant",tenantId); Add(q,"@id",notificationId); Add(q,"@customer",customerId); return await q.ExecuteNonQueryAsync(token)>0; }
    public async Task<int> MarkAllNotificationsReadAsync(Guid tenantId, Guid? customerId, CancellationToken token)
    { await using var c=new SqlConnection(ConnectionString); await c.OpenAsync(token); const string sql="UPDATE commerce.StorefrontFeedbackNotifications SET IsRead=1,ReadAtUtc=COALESCE(ReadAtUtc,SYSUTCDATETIME()) WHERE TenantId=@tenant AND IsRead=0 AND ((RecipientType=N'ERP' AND @customer IS NULL) OR (RecipientType=N'CUSTOMER' AND CustomerId=@customer));"; await using var q=new SqlCommand(sql,c); Add(q,"@tenant",tenantId); Add(q,"@customer",customerId); return await q.ExecuteNonQueryAsync(token); }
    public async Task<IReadOnlyCollection<StorefrontFeedbackAttachmentDto>> AttachmentsAsync(Guid tenantId, Guid ticketId, Guid? customerId, bool includeInternal, CancellationToken token)
    { await using var c=new SqlConnection(ConnectionString); await c.OpenAsync(token); const string sql="SELECT a.AttachmentId,a.OriginalFileName,a.ContentType,a.SizeBytes,a.ScanStatus,a.CreatedAtUtc FROM commerce.StorefrontFeedbackAttachments a JOIN commerce.StorefrontFeedbackTickets t ON t.TicketId=a.TicketId WHERE a.TenantId=@tenant AND a.TicketId=@ticket AND (@internal=1 OR a.IsInternal=0) AND (@customer IS NULL OR t.CustomerId=@customer) ORDER BY a.CreatedAtUtc;"; await using var q=new SqlCommand(sql,c); Add(q,"@tenant",tenantId); Add(q,"@ticket",ticketId); Add(q,"@customer",customerId); Add(q,"@internal",includeInternal); var rows=new List<StorefrontFeedbackAttachmentDto>(); await using var r=await q.ExecuteReaderAsync(token); while(await r.ReadAsync(token)) rows.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetInt64(3),r.GetString(4),r.GetDateTimeOffset(5))); return rows; }
    public async Task<StorefrontFeedbackAttachmentDownload?> ReadAttachmentAsync(Guid tenantId, Guid ticketId, Guid attachmentId, Guid? customerId, bool includeInternal, CancellationToken token)
    { await using var c=new SqlConnection(ConnectionString); await c.OpenAsync(token); const string sql="SELECT a.OriginalFileName,a.ContentType,a.StorageProvider,a.ObjectKey,COALESCE(a.StorageContent,0x),a.ScanStatus,a.IsInternal FROM commerce.StorefrontFeedbackAttachments a JOIN commerce.StorefrontFeedbackTickets t ON t.TicketId=a.TicketId WHERE a.TenantId=@tenant AND a.TicketId=@ticket AND a.AttachmentId=@id AND (@customer IS NULL OR t.CustomerId=@customer);"; await using var q=new SqlCommand(sql,c); Add(q,"@tenant",tenantId); Add(q,"@ticket",ticketId); Add(q,"@id",attachmentId); Add(q,"@customer",customerId); await using var r=await q.ExecuteReaderAsync(token); if(!await r.ReadAsync(token)||(!includeInternal&&r.GetBoolean(6))||!r.GetString(5).Equals("CLEAN",StringComparison.OrdinalIgnoreCase)) return null; var file=r.GetString(0); var type=r.GetString(1); var provider=r.GetString(2); var key=r.IsDBNull(3)?null:r.GetString(3); var bytes=(byte[])r[4]; await r.CloseAsync(); var content=await media.ReadStorefrontAsync(new(tenantId,provider,key,bytes,type),token); return content is null?null:new(content.Content,type,file); }
    public async Task<StorefrontFeedbackAttachmentDto> AddAttachmentAsync(Guid tenantId, Guid ticketId, Guid? customerId, bool includeInternal, string fileName, string contentType, byte[] content, CancellationToken token)
    { if(content.Length==0||content.Length>5*1024*1024) throw new BusinessRuleException("Attachments must be between 1 byte and 5 MB."); if(!AllowedSignature(content,contentType)) throw new BusinessRuleException("Only valid JPEG, PNG, WebP, or PDF files are allowed."); var scanResult=await scanner.ScanAsync(content,token); var scan=scanResult switch { StorefrontAttachmentScanResult.Clean=>"CLEAN", StorefrontAttachmentScanResult.Infected=>"BLOCKED", StorefrontAttachmentScanResult.Failed=>"FAILED", _=>"PENDING" }; await using var c=new SqlConnection(ConnectionString); await c.OpenAsync(token); await using var check=new SqlCommand("SELECT COUNT(1),COALESCE(MAX(CASE WHEN CustomerId=@customer THEN 1 ELSE 0 END),0) FROM commerce.StorefrontFeedbackTickets WHERE TenantId=@tenant AND TicketId=@ticket;",c); Add(check,"@tenant",tenantId);Add(check,"@ticket",ticketId);Add(check,"@customer",customerId);await using var cr=await check.ExecuteReaderAsync(token);if(!await cr.ReadAsync(token)||cr.GetInt32(0)!=1||(customerId.HasValue&&cr.GetInt32(1)!=1))throw new EntityNotFoundException("Feedback ticket was not found.");await cr.CloseAsync();await using var count=new SqlCommand("SELECT COUNT(1) FROM commerce.StorefrontFeedbackAttachments WHERE TenantId=@tenant AND TicketId=@ticket AND IsInternal=@internal;",c);Add(count,"@tenant",tenantId);Add(count,"@ticket",ticketId);Add(count,"@internal",includeInternal);if((int)(await count.ExecuteScalarAsync(token)??0)>=3)throw new BusinessRuleException("A ticket can have at most three attachments.");var id=Guid.NewGuid();var stored=await media.StoreStorefrontAsync(new(tenantId,"feedback",id,content,content,contentType),token);await using var insert=new SqlCommand("INSERT commerce.StorefrontFeedbackAttachments(AttachmentId,TenantId,TicketId,CustomerId,OriginalFileName,ContentType,SizeBytes,StorageProvider,ObjectKey,StorageContent,ScanStatus,IsInternal) VALUES(@id,@tenant,@ticket,@customer,@file,@type,@size,@provider,@key,@content,@scan,@internal);",c);Add(insert,"@id",id);Add(insert,"@tenant",tenantId);Add(insert,"@ticket",ticketId);Add(insert,"@customer",customerId);var safe=Path.GetFileName(fileName);Add(insert,"@file",safe[..Math.Min(255,safe.Length)]);Add(insert,"@type",contentType);Add(insert,"@size",content.LongLength);Add(insert,"@provider",stored.Provider);Add(insert,"@key",stored.ObjectKey);Add(insert,"@content",stored.Provider.Equals(ProductImageStorageProviders.Database,StringComparison.OrdinalIgnoreCase)?content:(object)DBNull.Value);Add(insert,"@scan",scan);Add(insert,"@internal",includeInternal);await insert.ExecuteNonQueryAsync(token);return new(id,safe,contentType,content.LongLength,scan,DateTimeOffset.UtcNow); }
    private async Task QueueExternalDeliveriesAsync(Guid tenantId, Guid ticketId, CancellationToken token)
    {
        await using var c = new SqlConnection(ConnectionString); await c.OpenAsync(token);
        const string sql = """
INSERT commerce.StorefrontFeedbackNotificationDeliveries(TenantId,NotificationId,TicketId,Channel,RecipientReference,TemplateKey)
SELECT n.TenantId,n.NotificationId,n.TicketId,N'EMAIL',CASE WHEN n.RecipientType=N'CUSTOMER' THEN c.Email ELSE NULL END,n.NotificationType
FROM commerce.StorefrontFeedbackNotifications n LEFT JOIN sales.Customers c ON c.TenantId=n.TenantId AND c.CustomerId=n.CustomerId
WHERE n.TenantId=@tenant AND n.TicketId=@ticket
  AND NOT EXISTS(SELECT 1 FROM commerce.StorefrontFeedbackNotificationDeliveries d WHERE d.NotificationId=n.NotificationId AND d.Channel=N'EMAIL');
INSERT commerce.StorefrontFeedbackNotificationDeliveries(TenantId,NotificationId,TicketId,Channel,RecipientReference,TemplateKey)
SELECT n.TenantId,n.NotificationId,n.TicketId,N'WHATSAPP',c.Mobile,n.NotificationType
FROM commerce.StorefrontFeedbackNotifications n JOIN sales.Customers c ON c.TenantId=n.TenantId AND c.CustomerId=n.CustomerId
WHERE n.TenantId=@tenant AND n.TicketId=@ticket AND n.RecipientType=N'CUSTOMER'
  AND NOT EXISTS(SELECT 1 FROM commerce.StorefrontFeedbackNotificationDeliveries d WHERE d.NotificationId=n.NotificationId AND d.Channel=N'WHATSAPP');
""";
        await using var q = new SqlCommand(sql, c); Add(q, "@tenant", tenantId); Add(q, "@ticket", ticketId); await q.ExecuteNonQueryAsync(token);
    }

    private async Task CreateNotificationsAsync(Guid tenantId, StorefrontFeedbackTicketDto ticket, string eventType, CancellationToken token)
    { await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);Guid? customerId=null;await using(var lookup=new SqlCommand("SELECT CustomerId FROM commerce.StorefrontFeedbackTickets WHERE TenantId=@tenant AND TicketId=@ticket;",c)){Add(lookup,"@tenant",tenantId);Add(lookup,"@ticket",ticket.TicketId);var value=await lookup.ExecuteScalarAsync(token);customerId=value is Guid id?id:null;}var title=eventType=="NEW_TICKET"?"New customer feedback":eventType=="CUSTOMER_REPLY"?"Customer replied to feedback":"Feedback ticket updated";var message=$"{ticket.TicketReference}: {ticket.Subject}";var entries=new List<(string,Guid?,string)>{("ERP",null,$"ERP:{ticket.TicketId}:{eventType}")};if(customerId.HasValue)entries.Add(("CUSTOMER",customerId,$"CUSTOMER:{ticket.TicketId}:{eventType}"));foreach(var entry in entries){await using var q=new SqlCommand("IF NOT EXISTS(SELECT 1 FROM commerce.StorefrontFeedbackNotifications WHERE TenantId=@tenant AND IdempotencyKey=@key) INSERT commerce.StorefrontFeedbackNotifications(TenantId,TicketId,CustomerId,RecipientType,NotificationType,Title,Message,IdempotencyKey) VALUES(@tenant,@ticket,@customer,@recipient,@type,@title,@message,@key);",c);Add(q,"@tenant",tenantId);Add(q,"@ticket",ticket.TicketId);Add(q,"@customer",entry.Item2);Add(q,"@recipient",entry.Item1);Add(q,"@type",eventType);Add(q,"@title",title);Add(q,"@message",message);Add(q,"@key",entry.Item3);await q.ExecuteNonQueryAsync(token);}}
    private static bool AllowedSignature(byte[] bytes,string type)=>type.ToLowerInvariant() switch {"image/jpeg"=>bytes.Length>3&&bytes[0]==0xff&&bytes[1]==0xd8&&bytes[2]==0xff,"image/png"=>bytes.Length>8&&bytes[0]==0x89&&bytes[1]==0x50&&bytes[2]==0x4e&&bytes[3]==0x47,"image/webp"=>bytes.Length>12&&bytes[0]==0x52&&bytes[1]==0x49&&bytes[2]==0x46&&bytes[3]==0x46&&bytes[8]==0x57&&bytes[9]==0x45&&bytes[10]==0x42&&bytes[11]==0x50,"application/pdf"=>bytes.Length>4&&bytes[0]==0x25&&bytes[1]==0x50&&bytes[2]==0x44&&bytes[3]==0x46,_=>false};
